import{F as e,_ as t,f as n,h as r,j as i,n as a}from"./chunks/shared.rYHlazZf.js";var o=JSON.parse(`{"title":"Administrar conexiones LIVE","description":"","frontmatter":{"title":"Administrar conexiones LIVE","docId":"user.live.connections","translationKey":"user.live.connections","locale":"es","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"446118d4c202b645dd93867f1715484cbd9876f940ba229ac26e4b7f24bc4cbc","translationRevision":"78856793407bc9b944189e635b13628c244375f460d97f685fa20cd102ed28d3","order":10},"headers":[],"relativePath":"es/user/live/connections.md","filePath":"es/user/live/connections.md","lastUpdated":1795735295000}`),s={name:`es/user/live/connections.md`};function c(a,o,s,c,l,u){let d=e(`DemoFrame`);return i(),n(`div`,null,[o[0]||=r(`<h1 id="manage-live-connections" tabindex="-1">Administrar conexiones LIVE <a class="header-anchor" href="#manage-live-connections" aria-label="Permalink to “Administrar conexiones LIVE”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo y requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “Objetivo y requisitos”">​</a></h2><p>Conecta con un creador concreto, comprende la reconexión y configura los servidores de plugins por separado. Necesitas una <a href="./../installation.html">instalación de escritorio</a>, acceso a Internet y el identificador del creador. Consulta los <a href="./../requirements.html">requisitos</a> antes de investigar problemas del sistema operativo.</p><h2 id="connect-deliberately" tabindex="-1">Conectar con intención <a class="header-anchor" href="#connect-deliberately" aria-label="Permalink to “Conectar con intención”">​</a></h2><ol><li>Abre <strong>Connections</strong>. Introduce el identificador, con o sin <code>@</code>; el nombre visible no es el mismo dato.</li><li>Comienza con <strong>Use Cookie</strong> desactivado. Si TikTok exige una sesión autorizada, actívalo e introduce la cookie únicamente en el campo oculto. Las cookies permanecen en memoria; no las pegues en diagnósticos ni en ajustes de Cloud.</li><li>Deja <strong>Monitor and auto-connect</strong> desactivado para un intento directo y pulsa <strong>Connect</strong>. Lee el estado y cualquier error antes de repetirlo.</li><li>Comprueba en el <a href="./feed.html">feed LIVE</a> que aparecen el creador correcto y un evento nuevo. Una sala conectada pero tranquila puede no mostrar actividad.</li><li>Usa <strong>Reconnect</strong> para el mismo creador o <strong>Disconnect</strong> antes de cambiarlo. Durante un intento en curso, <strong>Cancel</strong> permite detenerlo.</li></ol><p>Tras una conexión directa satisfactoria, activa la supervisión para esperar a que el creador inicie un LIVE. Esperar y comprobar son estados distintos de estar conectado. Detén la supervisión antes de editar un identificador bloqueado. Seleccionar un creador reciente inicia la conexión; no se limita a rellenar el campo.</p><p>El explorador ofrece salas descubiertas, pero sus resultados pueden caducar. Actualízalos antes de asumir que siguen disponibles. Los servidores de plugins del panel inferior configuran servicios propios; conectar un plugin no autentica TikTok ni Cloud.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado y estado <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to “Resultado esperado y estado”">​</a></h2><p>Están disponibles las conexiones directas, la supervisión y los controles de plugins. Reconectar al mismo creador conserva el contexto del feed; cambiarlo inicia otro. El acceso real a TikTok depende de la sala y la sesión externas; una prueba local satisfactoria no lo garantiza.</p><h2 id="recovery" tabindex="-1">Recuperación <a class="header-anchor" href="#recovery" aria-label="Permalink to “Recuperación”">​</a></h2><p>Si la sala está desconectada, confirma que el creador está en directo. Ante errores de sesión o límites de solicitudes, respeta la condición de reintento indicada. Reconectar repetidamente no renueva la autenticación. Consulta <a href="./../preferences/troubleshooting.html">solución de problemas</a> para registrar el componente y la hora sin revelar credenciales.</p><p>Pruébalo interactivamente antes de tocar tu configuración real:</p>`,12),t(d,{scenario:`connection`,locale:`es`,panel:`connection`,title:`Prueba el panel de conexión LIVE`}),o[1]||=r(`<h2 id="command-line-operations" tabindex="-1">Operaciones de línea de comandos <a class="header-anchor" href="#command-line-operations" aria-label="Permalink to “Operaciones de línea de comandos”">​</a></h2><p>Cada operación de esta guía también está disponible desde la CLI: sin conexión, scriptable y apta para agentes. Las líneas de uso son sintaxis del parser y permanecen en inglés en todos los idiomas.</p><table tabindex="0"><thead><tr><th>Comando</th><th>Resumen</th></tr></thead><tbody><tr><td><code>tiktools live connect --unique-id &lt;id&gt; --session-cookie &lt;cookie&gt; [--room-id &lt;id&gt;]</code></td><td>conectar a una sala en vivo</td></tr><tr><td><code>tiktools live pick --session-cookie &lt;cookie&gt;</code></td><td>elegir una sala en vivo interactivamente</td></tr><tr><td><code>tiktools live channels [--keyword text] [--offset N] [--limit N] [--session-cookie &lt;cookie&gt;]</code></td><td>descubrir canales en vivo; funciona sin sesión</td></tr><tr><td><code>tiktools live disconnect</code></td><td>desconectar de la sala actual <strong>destructivo</strong></td></tr><tr><td><code>tiktools live status</code></td><td>estado actual de la conexión</td></tr></tbody></table><p>Consulta la <a href="./../../developer/cli.html">referencia completa de comandos</a> para las convenciones, la salida JSON y los marcadores de operaciones destructivas.</p>`,4)])}var l=a(s,[[`render`,c]]);export{o as __pageData,l as default};